     7	/**
     8	 * Closes the last RHP flow, if there is only one, closes the entire RHP.
     9	 */
    10	export default function closeRHPFlow(navigationRef: NavigationContainerRef<RootStackParamList>) {
    11	    if (!navigationRef.isReady()) {
    12	        return;
    13	    }
    14	    const state = navigationRef.getState();
    15	    const lastRoute = state.routes.at(-1);
    16	    const isLastRouteRHP = lastRoute?.name === NAVIGATORS.RIGHT_MODAL_NAVIGATOR;
    17	
    18	    if (!isLastRouteRHP) {
    19	        Log.warn('RHP Navigator has not been found when calling closeRHPFlow function');
    20	        return;
    21	    }
    22	
    23	    let target = state.key;
    24	
    25	    const hasMoreThanOneRoute = lastRoute?.state?.routes?.length && lastRoute.state.routes.length > 1;
    26	    if (lastRoute?.state?.key && hasMoreThanOneRoute) {
    27	        target = lastRoute.state.key;
    28	    }
    29	    navigationRef.dispatch({...StackActions.pop(), target});
    30	}
